    for color, points in by_color.items():
        if color == 4:
            continue

        # Nearby fragments belong to one seed; separated objects of a color
        # are handled independently.
        remaining = set(points)
        groups = []
        while remaining:
            start = remaining.pop()
            group = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                near = [p for p in remaining
                        if abs(p[0]-r) <= 2 and abs(p[1]-c) <= 2]
                for p in near:
                    remaining.remove(p)
                    group.add(p)
                    stack.append(p)
            groups.append(group)

        for seeds in groups:
            options = []
            for dr in range(h):
                for dc in range(w):
                    placed = {(r+dr, c+dc) for r, c in shape}
                    if seeds <= placed:
                        # Prefer the placement whose full shape is centered
                        # closest to the seed fragment.
                        seed_center = (
                            (min(r for r, c in seeds) + max(r for r, c in seeds)) / 2,
                            (min(c for r, c in seeds) + max(c for r, c in seeds)) / 2
                        )
                        shape_center = (
                            dr + (min(r for r, c in shape) + max(r for r, c in shape)) / 2,
                            dc + (min(c for r, c in shape) + max(c for r, c in shape)) / 2
                        )
                        score = ((seed_center[0]-shape_center[0])**2 +
                                 (seed_center[1]-shape_center[1])**2)
                        options.append((score, dr, dc, placed))

            if options:
                _, _, _, placed = min(options, key=lambda x: (x[0], x[1], x[2]))
